INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginne ich hier ohne Planung?', 2, '[{"text": "Nein", "correct": true, "because": "Sprint-Planung ist zentral"}, {"text": "Ja", "correct": false, "because": "Strukturierter Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst in diesem Prozess?', 3, '[{"text": "Backlog erstellen", "correct": true, "because": "Anforderungen definieren"}, {"text": "Sprint planen", "correct": false, "because": "Folgt Backlog"}, {"text": "Daily Scrum", "correct": false, "because": "Während des Sprints"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu diesem Ablauf?', 5, '[{"text": "Sprint Review", "correct": true, "because": "Ergebnisse prüfen"}, {"text": "Retrospective", "correct": true, "because": "Prozess verbessern"}, {"text": "Einmalige Planung", "correct": false, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Daily Scrum ist täglich. b) Retrospective ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Retrospective essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesem Ansatz?', 4, '[{"text": "Backlog", "correct": false, "because": "Grundlage der Arbeit"}, {"text": "Sprint-Planung", "correct": false, "because": "Start jedes Zyklus"}, {"text": "Endlose Entwicklung", "correct": true, "because": "Sprint-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier nur einmal plane?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Sprint wird geplant"}, {"text": "Ja", "correct": false, "because": "Iterativer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase wähle ich, um tägliche Updates zu teilen?', 3, '[{"text": "Daily Scrum", "correct": true, "because": "Täglicher Austausch"}, {"text": "Sprint Review", "correct": false, "because": "Am Sprint-Ende"}, {"text": "Retrospective", "correct": false, "because": "Prozessreflexion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sichern den Fortschritt?', 5, '[{"text": "Sprint-Planung", "correct": true, "because": "Ziele festlegen"}, {"text": "Daily Scrum", "correct": true, "because": "Koordination prüfen"}, {"text": "Einmalige Reviews", "correct": false, "because": "Jeder Sprint geprüft"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Backlog ist die Basis. b) Daily Scrum ist selten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Daily Scrum täglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Sprint Review", "correct": false, "because": "Ergebnisse zeigen"}, {"text": "Retrospective", "correct": false, "because": "Verbesserung fördern"}, {"text": "Kontinuierlicher Fluss", "correct": true, "because": "Sprint-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Planung hier einmalig?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Sprint geplant"}, {"text": "Ja", "correct": false, "because": "Iterativer Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente verbessern den Prozess?', 4, '[{"text": "Retrospective", "correct": true, "because": "Reflexion fördern"}, {"text": "Sprint Review", "correct": true, "because": "Feedback einholen"}, {"text": "Feste Deadlines", "correct": false, "because": "Sprint-Zyklen flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Backlog arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Backlog ist Basis"}, {"text": "Ja", "correct": false, "because": "Anforderungen nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich vor jedem Zyklus?', 3, '[{"text": "Sprint-Planung", "correct": true, "because": "Ziele definieren"}, {"text": "Daily Scrum", "correct": false, "because": "Während des Sprints"}, {"text": "Retrospective", "correct": false, "because": "Nach dem Sprint"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Sprint Review zeigt Ergebnisse. b) Daily Scrum ist wöchentlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Daily Scrum täglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Regelmäßige Lieferung", "correct": true, "because": "Sprint-Zyklen"}, {"text": "Kontinuierliche Verbesserung", "correct": true, "because": "Retrospective"}, {"text": "Einmalige Reflexion", "correct": false, "because": "Jeder Sprint geprüft"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Backlog", "correct": false, "because": "Basis der Arbeit"}, {"text": "Sprint-Planung", "correct": false, "because": "Start jedes Zyklus"}, {"text": "Endloser Prozess", "correct": true, "because": "Sprint-basiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Retrospective hier unwichtig?', 3, '[{"text": "Nein", "correct": true, "because": "Verbesserung zentral"}, {"text": "Ja", "correct": false, "because": "Jeder Sprint reflektiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier täglich abstimme?', 2, '[{"text": "Ja", "correct": true, "because": "Daily Scrum ist täglich"}, {"text": "Nein", "correct": false, "because": "Koordination nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach dem Sprint?', 4, '[{"text": "Sprint Review", "correct": true, "because": "Ergebnisse prüfen"}, {"text": "Daily Scrum", "correct": false, "because": "Während des Sprints"}, {"text": "Backlog erstellen", "correct": false, "because": "Vor dem Sprint"}]');
